<table border="1"><tr><th colspan="11">MANIFIESTO DE EQUIPAJE - VIAJE <?php echo (int)$cabecera['viaje_id'];?> - <?php echo htmlspecialchars($cabecera['ruta_nombre']);?></th></tr><tr><th>#</th><th>ASIENTO</th><th>PASAJERO</th><th>ETIQUETA</th><th>TIPO</th><th>DESCRIPCION</th><th>PIEZAS</th><th>PESO KG</th><th>FORMA PAGO</th><th>IMPORTE BS</th><th>ESTADO</th></tr><?php $n=1;$tot=0;foreach($equipajes as $e){$tot+=(float)$e['equipaje_importe'];?><tr><td><?php echo $n++;?></td><td><?php echo htmlspecialchars($e['asiento_numero']);?></td><td><?php echo htmlspecialchars($e['pasaje_nombre']);?></td><td><?php echo htmlspecialchars($e['equipaje_numeroetiqueta']);?></td><td><?php echo htmlspecialchars($e['equipaje_tipo']);?></td><td><?php echo htmlspecialchars($e['equipaje_descripcion']);?></td><td><?php echo (int)$e['equipaje_cantidad_piezas'];?></td><td><?php echo number_format($e['equipaje_peso'],2,'.','');?></td><td><?php echo htmlspecialchars($e['forma_nombre']);?></td><td><?php echo number_format($e['equipaje_importe'],2,'.','');?></td><td><?php echo htmlspecialchars($e['equipaje_estado']);?></td></tr><?php }?><tr><th colspan="9">TOTAL</th><th><?php echo number_format($tot,2,'.','');?></th><th></th></tr></table>